// ❌ OLD: no-cache or must-revalidate forces the browser to halt rendering
// and wait for a 304 Not Modified roundtrip (100-300ms latency) on every request.
app.get('/api/config', (req, res) => {
  res.set({
    'Cache-Control': 'no-cache, must-revalidate',
    'ETag': '"v1.2.3"'
  });
  res.json({ theme: 'dark' });
});

// ✅ NEW: Fresh for 60 seconds; if accessed between 60s and 24h, serves
// instantly from disk cache (0ms) and revalidates in the background.
app.get('/api/config', (req, res) => {
  res.set({
    'Cache-Control': 'public, max-age=60, stale-while-revalidate=86400',
    'ETag': '"v1.2.3"'
  });
  res.json({ theme: 'dark' });
});
